import React, { useState } from 'react';
import { Layout, Menu, MenuProps, Image } from 'antd';
import Sider from 'antd/es/layout/Sider';

const { Content } = Layout;
type MenuItem = Required<MenuProps>['items'][number];

interface GroupItem {
  key: string;
  label: string;
  seasonLabel: string;
  image: string;
}

const groupList: GroupItem[] = [
  { key: 's8-1', label: '第1天海选', seasonLabel: '第八届', image: '/group/image1.jpg' },
  { key: 's8-2', label: '第2天海选', seasonLabel: '第八届', image: '/group/image2.jpg' },
  { key: 's8-3', label: '第3天海选', seasonLabel: '第八届', image: '/group/image3.jpg' },
  { key: 's8-4', label: '第4天海选', seasonLabel: '第八届', image: '/group/image4.jpg' },
  { key: 's8-5', label: '第5天海选', seasonLabel: '第八届', image: '/group/image5.jpg' },
  { key: 's8-6', label: '第6天海选', seasonLabel: '第八届', image: '/group/image6.jpg' },
  { key: 's8-7', label: '第7天海选', seasonLabel: '第八届', image: '/group/image7.jpg' },
  { key: 's8-8', label: '第8天海选', seasonLabel: '第八届', image: '/group/image8.jpg' },
  { key: 's8-9', label: '复活赛', seasonLabel: '第八届', image: '/group/image9.jpg' },
  { key: 's8-10', label: '淘汰赛', seasonLabel: '第八届', image: '/group/image10.jpg' },
];

const Group: React.FC = () => {
  const [selectedImage, setSelectedImage] = useState<string>('s8-10');

  function getItem(
    label: React.ReactNode,
    key: React.Key,
    icon?: React.ReactNode,
    children?: MenuItem[],
  ): MenuItem {
    return {
      key,
      icon,
      children,
      label,
    } as MenuItem;
  }

  function getItems(): MenuItem[]{ 
    const groupBySeason: Map<string, MenuItem[]> = new Map();
    groupList.forEach(item => {
      const season = item.seasonLabel;
      if (!groupBySeason.has(season)) {
        groupBySeason.set(season, []);
      }
      groupBySeason.get(season)?.push(getItem(item.label, item.key));
    });
    return Array.from(groupBySeason).map(([season, seasonItems]) => {
      return getItem(season, season, undefined, seasonItems);
    });
  }

  return (
    <Layout>
      <Sider width="150px">
        <Menu
          theme='dark'
          onClick={(e) => setSelectedImage(e.key)}
          // style={{ padding: '20px' }}
          defaultSelectedKeys={[selectedImage.toString()]}
          items={getItems()}
          mode="inline"
        />
      </Sider>
      <Content style={{ padding: '20px', textAlign: 'center', backgroundColor: '#38b', display: 'flex', flexDirection: 'column', alignItems: "center", }}>
        <Image
          src={groupList.find(item => item.key === selectedImage)?.image}
          style={{ maxWidth: '80%', maxHeight: '160vh' }}
        />
      </Content>
    </Layout>
  );
};

export default Group;