import React, { useEffect, useState } from "react";
import { Select, Spin } from "antd";
import http from "./http";
import Table, { ColumnsType } from "antd/es/table";
import Title from "antd/es/typography/Title";
import "./Table.css";

const { Option } = Select;

interface CharacterMeta {
  id: number;
  display_name: string;
  alias: string[];
}

interface MatchRecord {
  match: string;
  date: string;
  season: number;
  vote: number;
  rank: number;
  rate_global: number;
  rate_group: number;
  key: string;
}

interface CharacterRecordData {
  id: number;
  name: string;
  records: MatchRecord[];
}

const CharacterRecord: React.FC = () => {
  const [characterList, setCharacterList] = useState<CharacterMeta[]>([]);
  const [data, setData] = useState<CharacterRecordData[] | null>(null);
  const [character, setCharacter] = useState<CharacterMeta | null>(null);
  const [loading, setLoading] = useState(true);

  let filteredData: MatchRecord[] = [];
  if (character?.id !== undefined && data) {
    filteredData = data.find((item) => item.id === character?.id)?.records || [];
  }

  useEffect(() => {
    http()
      .get("/characters.json")
      .then((response) => {
        const _data = response.data as CharacterMeta[];
        _data.sort((a, b) => a.display_name.localeCompare(b.display_name));
        setCharacterList(_data);
      })
      .catch((error) => {
        console.error(error);
      }).finally(() => {
        setLoading(false);
      });
  }, []);

  const handleSelectChange = (key: number) => {
    setCharacter(characterList.find((char) => char.id === key) || null);
    if (!data) {
      setLoading(true);
      http()
        .get('/character_records.json')
        .then((response) => {
          const _data = response.data as CharacterRecordData[];
          _data.forEach((item) => {
            item.records.forEach((record) => {
              record.key = `${item.id}-${record.match}-${record.date}`;
            });
          });
          setData(_data);
        })
        .catch((error) => {
          console.error(error);
        })
        .finally(() => {
          setLoading(false);
        });
    }
  };

  const columns: ColumnsType<MatchRecord> = [
    {
      title: '届次',
      dataIndex: 'season',
      key: 'season',
      align: "center",
      onFilter: (value, record) => record.season === value,
      sorter: (a, b) => a.season - b.season,
    },
    {
      title: '比赛',
      dataIndex: 'match',
      key: 'match',
      align: "center",
      sorter: (a, b) => a.match.localeCompare(b.match),
    },
    {
      title: '日期',
      dataIndex: 'date',
      key: 'date',
      align: "center",
      sorter: (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
      defaultSortOrder: 'descend',
    },
    {
      title: '排名',
      dataIndex: 'rank',
      key: 'rank',
      align: "center",
      sorter: (a, b) => a.rank - b.rank,
    },
    {
      title: '票数',
      dataIndex: 'vote',
      key: 'vote',
      align: "center",
      sorter: (a, b) => a.vote - b.vote,
    },
    {
      title: '得票率(%)',
      dataIndex: 'rate_global',
      key: 'rate_global',
      align: "center",
      sorter: (a, b) => a.rate_global - b.rate_global,
    },
    {
      title: '组内得票率(%)',
      dataIndex: 'rate_group',
      key: 'rate_group',
      align: "center",
      sorter: (a, b) => a.rate_group - b.rate_group,
    }
  ];

  return (
    <>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          marginTop: 20,
        }}
      >
        <Select
          showSearch
          style={{ width: '60%', marginBottom: 20 }}
          placeholder="选择角色"
          optionFilterProp="alias"
          onChange={handleSelectChange}
        >
          {characterList.map((character) => (
            <Option key={character.id} value={character.id} alias={character.alias.join('|')}>
              {character.display_name}
            </Option>
          ))}
        </Select>
      </div>
      {character &&
        <Spin size="large" spinning={loading}>
          <Title level={2} className="vote-title" style={{marginBottom: '20px'}}>
            {character?.display_name}
          </Title>
          <Table
            columns={columns}
            dataSource={filteredData}
            bordered
            pagination={false}
            style={{ marginBottom: '20px' }}
          />
        </Spin>
      }
    </>
  );
};

export default CharacterRecord;
